      ),
      "",
    );
  } else {
    lines.push("No flaky tests detected.", "");
  }

  if (failed.length > 0) {
    lines.push(
      `## ❌ Failing tests (${failed.length})`,
      "",
      "| Test | Failed in | Message |",
      "| --- | --- | --- |",
      ...failed.map(
        (t) => `| \`${cell(t.id)}\` | ${cell(t.failedIn.join(", "))} | ${cell(t.message ?? "—")} |`,
      ),
      "",
    );
  }

  lines.push(
    "## 📊 Per-run breakdown",
    "",
    "| Run | Total | Passed | Failed | Skipped | Duration |",
    "| --- | ---: | ---: | ---: | ---: | ---: |",
